begin;
select no_plan();
delete from public.push_outbox;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000006101','push-a@test.invalid'),('00000000-0000-4000-8000-000000006102','push-b@test.invalid');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000006101','QA family','00000000-0000-4000-8000-000000006101');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000006101','00000000-0000-4000-8000-000000006101'),('10000000-0000-4000-8000-000000006101','00000000-0000-4000-8000-000000006102');
insert into auth.sessions(id,user_id) values(gen_random_uuid(),'00000000-0000-4000-8000-000000006101'),(gen_random_uuid(),'00000000-0000-4000-8000-000000006102');
insert into public.push_tokens(id,user_id,family_id,role,platform,token,token_type) values
 ('20000000-0000-4000-8000-000000006101','00000000-0000-4000-8000-000000006101','10000000-0000-4000-8000-000000006101','parent','ios','qa-token-one','apns'),
 ('20000000-0000-4000-8000-000000006102','00000000-0000-4000-8000-000000006102','10000000-0000-4000-8000-000000006101','parent','android','qa-token-two','fcm');
insert into public.push_outbox(family_id,audience,kind,payload) values('10000000-0000-4000-8000-000000006101','parents','exam_finished','{}');
select set_config('test.outbox',(select id::text from public.push_outbox),true);
update public.push_outbox set status='skipped_unconfigured',attempts=1;
insert into public.operations_members(user_id,role,expires_at) values('00000000-0000-4000-8000-000000006102','release',now()+interval '1 day');
insert into gina.push_deliveries(outbox_id,token_id,token_hash,status,last_lease) select id,'20000000-0000-4000-8000-000000006101',encode(extensions.digest('qa-token-one','sha256'),'hex'),'sent',gen_random_uuid() from public.push_outbox;
insert into gina.push_deliveries(outbox_id,token_id,token_hash,status,last_lease) select id,'20000000-0000-4000-8000-000000006102',encode(extensions.digest('qa-token-two','sha256'),'hex'),'unconfigured',gen_random_uuid() from public.push_outbox;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000006101","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000006101"}}',true);
select throws_ok($$select public.release_push_operations()$$,'42501','forbidden','ordinary parent cannot read operational queue');
select throws_ok($$select public.release_retry_push(gen_random_uuid(),current_setting('test.outbox')::bigint,0,'Provider configuration checked.',true)$$,'42501','forbidden','ordinary parent cannot replay notifications');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000006102","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000006101"}}',true);
select is(jsonb_array_length(public.release_push_operations()->'rows'),1,'release operator sees attention queue');
select is(public.release_push_operations()#>>'{rows,0,retryable}','true','recent partial unconfigured event can be recovered');
select ok(public.release_push_operations()::text not like '%token%' and public.release_push_operations()::text not like '%family_id%' and public.release_push_operations()::text not like '%qa-token%','queue excludes device secrets and family identity');
select throws_ok($$select public.release_retry_push(gen_random_uuid(),current_setting('test.outbox')::bigint,0,'Provider configuration checked.',false)$$,'P0001','invalid_input','explicit confirmation required');
select throws_ok($$select public.release_retry_push(gen_random_uuid(),current_setting('test.outbox')::bigint,0,'ok',true)$$,'P0001','invalid_input','meaningful reason required');
select throws_ok($$select * from gina.push_recoveries$$,'42501',null,'raw recovery metadata is private');
select set_config('test.request',gen_random_uuid()::text,true);
create function pg_temp.retry(req uuid default current_setting('test.request')::uuid,rev int default 0) returns jsonb language sql as $$select public.release_retry_push(req,current_setting('test.outbox')::bigint,rev,'Provider configuration checked.',true)$$;
select is(pg_temp.retry()->>'revision','1','first recovery creates a new revision');
select is(pg_temp.retry()->>'revision','1','lost recovery reply returns same receipt');
select throws_ok($$select pg_temp.retry(gen_random_uuid(),0)$$,'P0001','push_recovery_changed','stale operator cannot reset a newer cycle');
select throws_ok($$select pg_temp.retry(gen_random_uuid(),1)$$,'P0001','push_recovery_unavailable','pending event cannot be requeued again');
reset role;
select is((select count(*)::int from gina.push_recoveries),1,'one explicit recovery event only');
select is((select outcomes->>'sent' from gina.push_recoveries),'1','previous successful count retained in audit');
select is((select count(*)::int from gina.push_deliveries where status='sent'),1,'accepted device receipt preserved');
select is((select count(*)::int from gina.push_deliveries where status<>'sent'),0,'only unsuccessful device receipts reset');
set local role service_role;
select set_config('test.lease',(select lease_id::text from public.push_claim_v2(1)),true);
select is((select token_id from public.push_delivery_targets(current_setting('test.outbox')::bigint,current_setting('test.lease')::uuid)),'20000000-0000-4000-8000-000000006102'::uuid,'recovered worker targets only previously unsuccessful device');
reset role;update public.push_outbox set status='failed',lease_id=null,claimed_at=null;set local role authenticated;
select is(pg_temp.retry(gen_random_uuid(),1)->>'revision','2','second explicit recovery allowed');
reset role;update public.push_outbox set status='failed';set local role authenticated;
select throws_ok($$select pg_temp.retry(gen_random_uuid(),2)$$,'P0001','push_recovery_unavailable','third operator recovery is blocked');
reset role;
update public.push_outbox set recovery_revision=0,created_at=now()-interval '25 hours';set local role authenticated;
select is(public.release_push_operations()#>>'{rows,0,retryable}','false','old events cannot be replayed as surprise notifications');
select throws_ok($$select pg_temp.retry(gen_random_uuid(),0)$$,'P0001','push_recovery_unavailable','24 hour cap enforced on server');
reset role;update public.push_outbox set created_at=now();insert into public.push_preferences(user_id,family_id,exams) values('00000000-0000-4000-8000-000000006102','10000000-0000-4000-8000-000000006101',false);set local role authenticated;
select is(public.release_push_operations()#>>'{rows,0,retryable}','false','no retry when remaining device owner opted out');
reset role;
update public.push_preferences set exams=true;
insert into gina.push_recoveries(request_id,outbox_id,actor_id,reason,outcomes,revision)
select gen_random_uuid(),current_setting('test.outbox')::bigint,'00000000-0000-4000-8000-000000006102','Earlier operational recovery.','{}',1 from generate_series(1,18);
set local role authenticated;
select throws_ok($$select pg_temp.retry(gen_random_uuid(),0)$$,'P0001','push_recovery_limited','actor hourly limit applies across requests');
reset role;
select is((select status from public.push_outbox),'failed','rate rejection does not change pending status');
set local role authenticated;
reset role;update public.operations_members set expires_at=now()-interval '1 second';set local role authenticated;
select throws_ok($$select public.release_push_operations()$$,'42501','forbidden','expired role blocks reads even with old JWT');
select throws_ok($$select pg_temp.retry()$$,'42501','forbidden','expired operator cannot replay a saved receipt');
reset role;
select lives_ok($$delete from public.families where id='10000000-0000-4000-8000-000000006101';set constraints all immediate;$$,'family deletion removes private recovery history');
select is((select count(*)::int from gina.push_recoveries),0,'no orphan recovery record');
select * from finish();rollback;
